"""
csv_stream.py

Streams a large CSV file, validates required columns, normalizes
timestamps to UTC, and aggregates totals by account — without loading
all rows into memory.
"""

from __future__ import annotations

import csv
import io
import logging
from collections import defaultdict
from dataclasses import dataclass, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Callable, Iterable, Iterator, Mapping, Sequence, TextIO, Union

logger = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Typed interfaces
# ---------------------------------------------------------------------------

CSVSource = Union[str, Path, io.StringIO, TextIO]


class ValidationError(Exception):
    """Raised when a CSV row fails validation."""


@dataclass(frozen=True)
class Row:
    """A validated, normalized row."""
    account: str
    amount: float
    timestamp: datetime


@dataclass
class Aggregation:
    """Aggregation results per account."""
    totals: dict[str, float] = field(default_factory=dict)
    counts: dict[str, int] = field(default_factory=dict)
    first_seen: dict[str, datetime] = field(default_factory=dict)
    last_seen: dict[str, datetime] = field(default_factory=dict)
    rows_processed: int = 0
    rows_rejected: int = 0

    def merge(self, other: Aggregation) -> None:
        for acct, total in other.totals.items():
            self.totals[acct] = self.totals.get(acct, 0.0) + total
            self.counts[acct] = self.counts.get(acct, 0) + other.counts[acct]
        for acct, ts in other.first_seen.items():
            if acct not in self.first_seen or ts < self.first_seen[acct]:
                self.first_seen[acct] = ts
        for acct, ts in other.last_seen.items():
            if acct not in self.last_seen or ts > self.last_seen[acct]:
                self.last_seen[acct] = ts
        self.rows_processed += other.rows_processed
        self.rows_rejected += other.rows_rejected


@dataclass(frozen=True)
class Config:
    """Configuration for the CSV stream processor."""
    required_columns: tuple[str, ...] = ("account", "amount", "timestamp")
    account_col: str = "account"
    amount_col: str = "amount"
    timestamp_col: str = "timestamp"
    timestamp_formats: tuple[str, ...] = (
        "%Y-%m-%dT%H:%M:%S%z",      # ISO 8601 with offset
        "%Y-%m-%d %H:%M:%S%z",      # space-separated with offset
        "%Y-%m-%dT%H:%M:%S",        # naive ISO (assumed UTC)
        "%Y-%m-%d %H:%M:%S",        # naive (assumed UTC)
    )
    default_timezone: timezone = timezone.utc
    strict: bool = True  # raise on first invalid row if True, else skip
    chunk_size: int = 10_000


# ---------------------------------------------------------------------------
# Normalization helpers
# ---------------------------------------------------------------------------

def parse_timestamp(
    raw: str,
    formats: Sequence[str] = (),
    default_tz: timezone = timezone.utc,
) -> datetime:
    """Parse a timestamp string and normalize it to UTC."""
    raw = raw.strip()
    # Try ISO parsing first (handles most modern formats incl. Z suffix)
    try:
        dt = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        pass
    else:
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=default_tz)
        return dt.astimezone(timezone.utc)

    for fmt in formats:
        try:
            dt = datetime.strptime(raw, fmt)
        except ValueError:
            continue
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=default_tz)
        return dt.astimezone(timezone.utc)

    raise ValidationError(f"Unparseable timestamp: {raw!r}")


def parse_amount(raw: str) -> float:
    """Parse an amount string, stripping currency symbols and whitespace."""
    cleaned = raw.strip().replace("$", "").replace(",", "")
    try:
        return float(cleaned)
    except ValueError as exc:
        raise ValidationError(f"Unparseable amount: {raw!r}") from exc


# ---------------------------------------------------------------------------
# Core streaming logic
# ---------------------------------------------------------------------------

def _open_source(source: CSVSource) -> TextIO:
    if isinstance(source, (str, Path)):
        return open(source, "r", encoding="utf-8", newline="")
    return source


def validate_header(
    reader: csv.DictReader,
    required_columns: Sequence[str],
) -> None:
    """Ensure the CSV header contains all required columns."""
    header = reader.fieldnames or []
    missing = [c for c in required_columns if c not in header]
    if missing:
        raise ValidationError(
            f"CSV is missing required columns: {missing}. "
            f"Found: {header}"
        )


def iter_rows(
    source: CSVSource,
    config: Config,
) -> Iterator[Row]:
    """Lazily yield validated, normalized rows from the CSV source."""
    stream = _open_source(source)
    try:
        reader = csv.DictReader(stream)
        validate_header(reader, config.required_columns)

        for line_no, raw in enumerate(reader, start=2):  # header is line 1
            try:
                row = Row(
                    account=raw[config.account_col].strip(),
                    amount=parse_amount(raw[config.amount_col]),
                    timestamp=parse_timestamp(
                        raw[config.timestamp_col],
                        config.timestamp_formats,
                        config.default_timezone,
                    ),
                )
                if not row.account:
                    raise ValidationError("Empty account value")
                yield row
            except ValidationError as exc:
                if config.strict:
                    raise ValidationError(f"Line {line_no}: {exc}") from exc
                logger.warning("Skipping line %d: %s", line_no, exc)
                continue
    finally:
        if isinstance(source, (str, Path)):
            stream.close()


def aggregate(
    source: CSVSource,
    config: Config | None = None,
) -> Aggregation:
    """Stream the CSV and aggregate totals by account."""
    config = config or Config()
    agg = Aggregation()

    for row in iter_rows(source, config):
        agg.totals[row.account] = agg.totals.get(row.account, 0.0) + row.amount
        agg.counts[row.account] = agg.counts.get(row.account, 0) + 1
        if row.account not in agg.first_seen or row.timestamp < agg.first_seen[row.account]:
            agg.first_seen[row.account] = row.timestamp
        if row.account not in agg.last_seen or row.timestamp > agg.last_seen[row.account]:
            agg.last_seen[row.account] = row.timestamp
        agg.rows_processed += 1

    return agg


